<script setup>
import { reactive,ref,computed,onMounted } from 'vue';
import { api } from '../../services/api.js';
import { workspace,loadStores } from '../../services/workspace.js';
import { canFeature } from '../../services/auth.js';
import { notify } from '../../services/notifications.js';
import Icon from '../../components/Icon.vue';
import StoreWhatsapp from '../../components/StoreWhatsapp.vue';
const loading=ref(true),saving=ref(false),error=ref('');
const contact=reactive({email:'',phone:'',whatsapp:'',message:'¡Hola! Me gustaría consultar sobre sus productos.',showWhatsapp:false,showContactForm:false});
const waLink=computed(()=>contact.whatsapp.replace(/\D/g,'')?`https://wa.me/${contact.whatsapp.replace(/\D/g,'')}?text=${encodeURIComponent(contact.message)}`:'');
onMounted(async()=>{try{const data=await api.get(`/stores/${workspace.activeStoreId}`);Object.assign(contact,data.contact||{})}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{await api.put(`/stores/${workspace.activeStoreId}/contact`,{contact});await loadStores();notify.success('Datos de contacto actualizados.')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">CONVERSACIONES QUE ACERCAN</p><h1>Contacto</h1><p>Que tus clientes puedan encontrarte de la manera que les resulte más cómoda.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else @submit.prevent="save" class="p-form"><div class="p-two-column"><div><section class="p-section-card"><div class="p-section-title"><h2>Datos de tu negocio</h2><Icon name="phone"/></div><div class="p-form-grid"><div class="p-field"><label for="contact-email">Correo electrónico</label><input id="contact-email" v-model.trim="contact.email" type="email" :required="contact.showContactForm" placeholder="hola@mitienda.com"/></div><div class="p-field"><label for="contact-phone">Teléfono visible</label><input id="contact-phone" v-model.trim="contact.phone" type="tel" placeholder="+54 11 1234 5678" maxlength="40"/></div><div class="p-field full"><label class="p-check"><input v-model="contact.showContactForm" type="checkbox"/>Mostrar formulario para recibir consultas por correo</label><small>Las consultas llegan a este correo usando el SMTP configurado en la plataforma.</small></div></div></section><section v-if="canFeature('contact.whatsapp')||contact.showWhatsapp" class="p-section-card"><div class="p-section-title"><div><h2>WhatsApp de tu tienda</h2><p>Un acceso directo para que empiece la conversación.</p></div><Icon name="whatsapp" :size="22"/></div><div class="p-form-grid"><div class="p-field full"><label for="contact-whatsapp">Número de WhatsApp</label><input id="contact-whatsapp" v-model.trim="contact.whatsapp" type="tel" :disabled="!canFeature('contact.whatsapp')" :required="contact.showWhatsapp" placeholder="5491112345678" maxlength="40"/><small>Incluí código de país y área. Ejemplo para Argentina: 5491112345678.</small></div><div class="p-field full"><label for="contact-message">Mensaje inicial</label><textarea id="contact-message" v-model="contact.message" :disabled="!canFeature('contact.whatsapp')" maxlength="1000" rows="4"/><small>Se completa en el teléfono del cliente cuando abre el chat. El cliente decide enviarlo.</small></div><label class="p-check"><input v-model="contact.showWhatsapp" type="checkbox" :disabled="!canFeature('contact.whatsapp')&&!contact.showWhatsapp"/>Mostrar botón flotante de WhatsApp</label></div></section></div><aside class="p-order-summary"><div class="p-section-title"><h2>Vista previa</h2><Icon name="eye" :size="18"/></div><div class="p-whatsapp-preview"><div class="p-wa-bubble">{{contact.message||'El mensaje inicial aparecerá acá.'}}</div></div><div class="p-inline" style="justify-content:center;margin-top:20px"><StoreWhatsapp :href="waLink" preview/></div><p v-if="!waLink" class="p-help" style="text-align:center">Ingresá un número para probar la conversación.</p><p class="p-help" style="text-align:center;margin-top:15px">{{contact.showWhatsapp?'El botón aparecerá en tu tienda.':'Activá el botón flotante para mostrarlo en la tienda.'}}</p></aside></div><footer class="p-form-footer"><small>Los cambios se reflejan en el contacto de tu tienda.</small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':'Guardar contacto'}}</button></div></footer></form></div></template>
